BEGIN;
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY,order_number varchar(50) UNIQUE NOT NULL,customer_name varchar(120) NOT NULL,customer_email varchar(254) NOT NULL,customer_phone varchar(32) NOT NULL,package_slug varchar(16) NOT NULL CHECK(package_slug IN('HEMAT','REGULER','VIP')),template_slug varchar(80) NOT NULL,gross_amount integer NOT NULL CHECK(gross_amount>=0),status varchar(24) NOT NULL DEFAULT 'PENDING_PAYMENT' CHECK(status IN('DRAFT','PENDING_PAYMENT','PAID','PROCESSING','ACTIVE','EXPIRED','FAILED','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,provider varchar(24) NOT NULL DEFAULT 'MIDTRANS',provider_order_id varchar(50) UNIQUE NOT NULL,provider_transaction_id varchar(100),snap_token varchar(255),gross_amount integer NOT NULL CHECK(gross_amount>=0),transaction_status varchar(32) NOT NULL DEFAULT 'pending',fraud_status varchar(32),paid_at timestamptz,raw_notification jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());ALTER TABLE payments ADD COLUMN IF NOT EXISTS snap_token varchar(255);CREATE TABLE IF NOT EXISTS payment_events(id bigserial PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(id) ON DELETE RESTRICT,event_source varchar(24) NOT NULL CHECK(event_source IN('WEBHOOK','RECONCILIATION','SYSTEM')),event_type varchar(64) NOT NULL,transaction_status varchar(32),fraud_status varchar(32),payload jsonb,created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS rate_limit_buckets(scope varchar(64) NOT NULL,key_hash varchar(160) NOT NULL,window_bucket bigint NOT NULL,hits integer NOT NULL CHECK(hits>0),expires_at timestamptz NOT NULL,PRIMARY KEY(scope,key_hash,window_bucket));CREATE INDEX IF NOT EXISTS idx_rate_limit_buckets_expiry ON rate_limit_buckets(expires_at);CREATE TABLE IF NOT EXISTS invitations(id uuid PRIMARY KEY,order_id uuid UNIQUE NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,slug varchar(100) UNIQUE NOT NULL,template_slug varchar(80) NOT NULL,package_slug varchar(16) NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,is_published boolean NOT NULL DEFAULT false,active_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS rsvps(id uuid PRIMARY KEY,invitation_id uuid NOT NULL REFERENCES invitations(id) ON DELETE CASCADE,guest_name varchar(120) NOT NULL,guest_phone varchar(32),attendance varchar(16) NOT NULL CHECK(attendance IN('hadir','tidak_hadir','ragu')),guest_count smallint NOT NULL CHECK(guest_count BETWEEN 1 AND 10),notes varchar(500),created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS guest_messages(id uuid PRIMARY KEY,invitation_id uuid NOT NULL REFERENCES invitations(id) ON DELETE CASCADE,sender_name varchar(120) NOT NULL,relationship varchar(120),attendance varchar(16) NOT NULL CHECK(attendance IN('hadir','tidak_hadir','ragu')),message varchar(1000) NOT NULL,is_approved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);CREATE INDEX IF NOT EXISTS idx_payments_order_id ON payments(order_id);CREATE INDEX IF NOT EXISTS idx_payment_events_payment_created ON payment_events(payment_id,created_at DESC);CREATE INDEX IF NOT EXISTS idx_invitations_slug ON invitations(slug);CREATE INDEX IF NOT EXISTS idx_rsvps_invitation ON rsvps(invitation_id,created_at DESC);CREATE INDEX IF NOT EXISTS idx_guest_messages_invitation_approved ON guest_messages(invitation_id,is_approved,created_at DESC);COMMIT;
